from collections import Counter
from datetime import date, timedelta
tx = [  # (유저, 날짜, 카테고리, 금액, 시각)
    ("u1", date(2026, 11, 3), "카페", 4500, 8), ("u1", date(2026, 11, 4), "카페", 4800, 8),
    ("u1", date(2026, 11, 5), "편의점", 3000, 12), ("u1", date(2026, 10, 1), "여행", 300000, 15),
    ("u2", date(2026, 11, 8), "배달", 21000, 22), ("u2", date(2026, 11, 9), "배달", 18000, 23),
]
def profile(user, as_of, days=30):
    rows = [t for t in tx if t[0] == user and as_of - timedelta(days=days) < t[1] <= as_of]
    cats = Counter(t[2] for t in rows)
    morning = sum(1 for t in rows if 7 <= t[4] <= 9 and t[1].weekday() < 5)
    return {"user": user, "as_of": str(as_of), "spend_30d": sum(t[3] for t in rows),
            "top_category": cats.most_common(1)[0][0] if cats else None,
            "commuter_guess": morning >= 2,  # 규칙: 평일 아침 결제 2건 이상
            "rule_version": "v1"}
for u in ("u1", "u2"):
    print(profile(u, date(2026, 11, 10)))
# {'user': 'u1', 'as_of': '2026-11-10', 'spend_30d': 12300, 'top_category': '카페', 'commuter_guess': True, 'rule_version': 'v1'}
# {'user': 'u2', 'as_of': '2026-11-10', 'spend_30d': 39000, 'top_category': '배달', 'commuter_guess': False, 'rule_version': 'v1'}

ontology = {
    "entities": {"User": "mart.user_profile.user_id", "Merchant": "mart.merchant_profile.merchant_id"},
    "relations": [{"name": "PAYS_AT", "from": "User", "to": "Merchant",
                   "table": "mart.integrated_spend", "keys": ["user_id", "merchant_id"]}],
}
tables = {  # 칸 이름: 설명(비어 있으면 AI가 뜻을 모른다)
    "mart.user_profile": {"user_id": "토스 유저 번호", "spend_30d": "최근 30일 소비액(원)"},
    "mart.merchant_profile": {"merchant_id": "가맹점 번호", "grade": ""},
    "mart.integrated_spend": {"user_id": "토스 유저 번호", "amt": "결제 금액(원)"},
}
problems = []
for ent, ref in ontology["entities"].items():
    t, col = ref.rsplit(".", 1)
    if col not in tables.get(t, {}):
        problems.append(f"{ent}: {t} 에 키 {col} 없음")
for r in ontology["relations"]:
    for k in r["keys"]:
        if k not in tables[r["table"]]:
            problems.append(f"{r['name']}: {r['table']} 에 연결 키 {k} 없음")
for t, cols in tables.items():
    problems += [f"{t}.{c}: 설명 없음" for c, desc in cols.items() if not desc]
print("\n".join(problems) or "통과")
# PAYS_AT: mart.integrated_spend 에 연결 키 merchant_id 없음
# mart.merchant_profile.grade: 설명 없음
